package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	in := NewFastScanner(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	n := in.NextInt()
	k := in.NextInt()
	query := make([]int, n)
	for i := 0; i < n; i++ {
		query[i] = in.NextInt()
	}

	cost := 0
	availableBooks := make(map[int]struct{}, k)
	access := make([]int, 81)
	removable := -1

	for i := 0; i < n; i++ {
		access[query[i]]++
	}

	for i := 0; i < n; i++ {
		currentBook := query[i]
		_, doesNotContain := availableBooks[currentBook]
		if doesNotContain {
			cost++
		}

		if removable != -1 {
			delete(availableBooks, removable)
			removable = -1
		} else if len(availableBooks) == k && doesNotContain {
			removableBook := -1
			count := k
			known := make(map[int]struct{})
			for j := i + 1; j < n && count > 0; j++ {
				if _, ok := availableBooks[query[j]]; ok {
					if _, seen := known[query[j]]; !seen {
						count--
						known[query[j]] = struct{}{}
						removableBook = query[j]
					}
				}
			}
			if removableBook != -1 {
				delete(availableBooks, removableBook)
			} else {
				for book := range availableBooks {
					delete(availableBooks, book)
					break
				}
			}
		}

		availableBooks[currentBook] = struct{}{}
		access[currentBook]--
		if access[currentBook] == 0 {
			removable = currentBook
		}
	}

	out.WriteString(strconv.Itoa(cost))
	out.WriteByte('\n')
}

type FastScanner struct {
	data []byte
	idx  int
}

func NewFastScanner(r *os.File) *FastScanner {
	stat, _ := r.Stat()
	size := stat.Size()
	if size == 0 {
		size = 1 << 20
	}
	buf := make([]byte, size)
	n, _ := r.Read(buf)
	return &FastScanner{data: buf[:n], idx: 0}
}

func (s *FastScanner) NextInt() int {
	for s.idx < len(s.data) && s.data[s.idx] <= ' ' {
		s.idx++
	}
	neg := false
	if s.idx < len(s.data) && s.data[s.idx] == '-' {
		neg = true
		s.idx++
	}
	val := 0
	for s.idx < len(s.data) && s.data[s.idx] >= '0' && s.data[s.idx] <= '9' {
		val = val*10 + int(s.data[s.idx]-'0')
		s.idx++
	}
	if neg {
		return -val
	}
	return val
}

package main

import (
	"os"
	"strconv"
)

func main() {
	data, _ := os.ReadFile(os.Stdin)
	idx := 0
	n := nextInt(data, &idx)
	k := nextInt(data, &idx)
	query := make([]int, n)
	for i := 0; i < n; i++ {
		query[i] = nextInt(data, &idx)
	}

	access := make([]int, 81)
	for _, v := range query {
		access[v]++
	}

	availableBooks := make(map[int]struct{}, k)
	cost := 0
	removable := -1

	for i := 0; i < n; i++ {
		currentBook := query[i]
		_, exists := availableBooks[currentBook]
		doesNotContain := !exists

		if doesNotContain {
			cost++
		}

		if removable != -1 {
			delete(availableBooks, removable)
			removable = -1
		} else if len(availableBooks) == k && doesNotContain {
			removableBook := -1
			count := k
			known := make(map[int]struct{}, k)
			for j := i + 1; j < n && count > 0; j++ {
				b := query[j]
				if _, ok := availableBooks[b]; ok {
					if _, seen := known[b]; !seen {
						count--
						known[b] = struct{}{}
						removableBook = b
					}
				}
			}
			if removableBook != -1 {
				delete(availableBooks, removableBook)
			} else {
				for b := range availableBooks {
					delete(availableBooks, b)
					break
				}
			}
		}

		availableBooks[currentBook] = struct{}{}
		access[currentBook]--
		if access[currentBook] == 0 {
			removable = currentBook
		}
	}

	os.Stdout.WriteString(strconv.Itoa(cost) + "\n")
}

func nextInt(data []byte, idx *int) int {
	for *idx < len(data) && data[*idx] <= ' ' {
		*idx++
	}
	neg := false
	if data[*idx] == '-' {
		neg = true
		*idx++
	}
	val := 0
	for *idx < len(data) && data[*idx] >= '0' {
		val = val*10 + int(data[*idx]-'0')
		*idx++
	}
	if neg {
		return -val
	}
	return val
}

