func NewFastScanner(reader *bufio.Reader) *FastScanner {
	return &FastScanner{
		reader: reader,
		buf:    make([]byte, 1<<16),
		idx:    0,
		size:   0,
	}
}

func (fs *FastScanner) read() byte {
	if fs.idx >= fs.size {
		fs.size, _ = fs.reader.Read(fs.buf)
		fs.idx = 0
		if fs.size == 0 {
			return 0
		}
	}
	b := fs.buf[fs.idx]
	fs.idx++
	return b
}

func (fs *FastScanner) NextInt() int {
	var ret int
	c := fs.read()
	for c <= ' ' && c != 0 {
		c = fs.read()
	}
	neg := false
	if c == '-' {
		neg = true
		c = fs.read()
	}
	for c >= '0' && c <= '9' {
		ret = ret*10 + int(c-'0')
		c = fs.read()
	}
	if neg {
		return -ret
	}
	return ret
}

